<div class="nia-guide" id="niaGuide" aria-hidden="true"></div><div class="nia-guide-note" id="niaGuideNote" aria-live="polite"></div>
<button class="nia-fab" id="niaFab" type="button" aria-label="Otevřít Niu"><img class="nia-person-img" src="/assets/nia.png" alt="Nia"></button>
<div class="nia-panel" id="niaPanel" aria-hidden="true"><div class="nia-speech"><div class="nia-mini"><img src="/assets/nia.png" alt="Nia"></div><div class="nia-bubble"><div class="nia-name">Nia</div><div id="niaAnswer">Ahoj! S čím ti dnes můžu pomoct?</div></div></div><div class="nia-suggestions"><button type="button" data-nia-prompt="Co mám dnes udělat?">Co mám dnes udělat?</button><button type="button" data-nia-prompt="Ukaž mi nezaplacené faktury.">Nezaplacené faktury</button><button type="button" data-nia-prompt="Chci vytvořit fakturu.">Vytvořit fakturu</button></div><form class="nia-form" id="niaForm"><input type="hidden" name="_csrf" value="<?=View::e(Auth::csrf())?>"><input id="niaInput" name="prompt" autocomplete="off" placeholder="Napiš Nii, co potřebuješ…"><button type="submit">Poslat</button></form><a class="nia-link" href="/ai">Otevřít celý chat s Niou →</a></div>
<script>(function(){const fab=document.getElementById('niaFab'),panel=document.getElementById('niaPanel'),form=document.getElementById('niaForm'),input=document.getElementById('niaInput'),answer=document.getElementById('niaAnswer');if(!fab||!panel||!form)return;function open(){panel.classList.add('open');panel.setAttribute('aria-hidden','false');input.focus()}function close(){panel.classList.remove('open');panel.setAttribute('aria-hidden','true');fab.classList.remove('talking','thinking')}fab.addEventListener('click',()=>panel.classList.contains('open')?close():open());async function ask(text){text=text.trim();if(!text)return;input.value='';answer.innerHTML='<span class="nia-typing"><i></i><i></i><i></i></span>';fab.classList.add('thinking','talking');try{const fd=new FormData(form);fd.set('prompt',text);const r=await fetch('/ai/ask',{method:'POST',body:fd,headers:{'X-Requested-With':'fetch'}});const j=await r.json();if(!j.ok)throw new Error(j.error||'');answer.textContent=j.answer||'Hotovo.';if(j.pending)answer.textContent+=' Návrh akce čeká na potvrzení v celém AI chatu.';}catch(e){answer.textContent='Teď se mi nepodařilo odpovědět. Zkus to prosím znovu.';}finally{fab.classList.remove('thinking');setTimeout(()=>fab.classList.remove('talking'),700)}}form.addEventListener('submit',e=>{e.preventDefault();ask(input.value)});document.querySelectorAll('[data-nia-prompt]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.niaPrompt)));document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});})();</script>
<?php else: ?><?php include $file; ?><?php endif; ?><style>
.tour-live-shade{position:fixed;inset:0;z-index:110;pointer-events:none;background:radial-gradient(ellipse 180px 80px at calc(var(--x) + var(--w)/2) calc(var(--y) + var(--h)/2),transparent 0,transparent 72%,rgba(7,26,58,.52) 74%);}
.tour-live-shade:after{content:"";position:absolute;left:var(--x);top:var(--y);width:var(--w);height:var(--h);border:3px solid #5b46e8;border-radius:14px;box-shadow:0 0 0 5px rgba(91,70,232,.14);}
.tour-live-note{position:fixed;z-index:111;width:min(320px,calc(100vw - 24px));background:#fff;border:1px solid #dce6f3;border-radius:18px;padding:15px;box-shadow:0 18px 48px rgba(16,33,63,.22);font-size:13px;line-height:1.5}.tour-live-note strong{display:block;color:#5946e8;margin-bottom:4px}.tour-live-note p{margin:5px 0 0;color:#5e6f86}.tour-live-actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}.tour-live-actions .btn{width:auto}.tour-live-actions a{min-height:40px}
@media(max-width:760px){.tour-live-note{left:12px!important;right:12px;width:auto;top:auto!important;bottom:92px}.tour-live-shade:after{border-width:2px}}
</style><script>
(function(){
  const params=new URLSearchParams(location.search), tour=params.get('tour'), next=params.get('next');
  if(!tour) return;
  const targetMap={2:'customers',3:'documents',4:'jobs',5:'bank',6:'calendar'};
  const target=targetMap[tour]; if(!target) return;
  const el=document.querySelector('[data-guide="'+CSS.escape(target)+'"]'); if(!el) return;
  const shade=document.createElement('div'); shade.className='tour-live-shade';
  const note=document.createElement('div'); note.className='tour-live-note';
  const titles={customers:'CRM / Zákazníci',documents:'Doklady',jobs:'Zakázky',bank:'Banka a párování plateb',calendar:'Kalendář'};
  const texts={customers:'Tady spravuješ zákazníky, jejich historii, doklady a zakázky.',documents:'Tady vystavuješ faktury, nabídky, objednávky a další doklady.',jobs:'Tady vedeš zakázky, rozpočet, práci, materiál a výsledek.',bank:'Tady sleduješ transakce a páruješ přijaté platby k fakturám.',calendar:'Tady máš termíny, schůzky a úkoly na jednom místě.'};
  note.innerHTML='<strong>Nia · krok '+tour+' z 7</strong><div>'+titles[tour]+'</div><p>'+texts[tour]+'</p><div class="tour-live-actions"><a class="btn primary" href="/uvod?step='+encodeURIComponent(next||'7')+'">Pokračovat →</a><a class="btn" href="/uvod?step='+encodeURIComponent(tour)+'">Zpět</a></div>';
  document.body.append(shade,note);
  function place(){
    const r=el.getBoundingClientRect();
    shade.style.setProperty('--x',Math.max(8,r.left-5)+'px');shade.style.setProperty('--y',Math.max(8,r.top-5)+'px');shade.style.setProperty('--w',Math.min(r.width+10,window.innerWidth-16)+'px');shade.style.setProperty('--h',Math.min(r.height+10,window.innerHeight-16)+'px');
    const left=Math.min(Math.max(12,r.left),Math.max(12,window.innerWidth-332));
    const top=Math.min(Math.max(76,r.bottom+14),Math.max(76,window.innerHeight-210));
    note.style.left=left+'px';note.style.top=top+'px';
  }
  place(); window.addEventListener('resize',place); window.addEventListener('scroll',place,{passive:true});
})();
</script></body></html>
